    private void btnCalcularActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnCalcularActionPerformed
        double numerador;
        double denominador;
        String entradaNumerador = String.valueOf(txtNumerador.getText());
        String entradaDenominador = String.valueOf(txtDenominador.getText());
        numerador = Double.parseDouble(entradaNumerador);
        denominador = Double.parseDouble(entradaDenominador);
        try {
            if (denominador == 0) {
                JOptionPane.showMessageDialog(this, "El denominador no puede ser cero", "Error aritmético", JOptionPane.ERROR_MESSAGE);
                throw new ArithmeticException("El denominador no puede ser cero");
            }
            double cociente = numerador/denominador;
            txtCociente.setText(String.valueOf(cociente));
        } catch (ArithmeticException e) {
        }
    }//GEN-LAST:event_btnCalcularActionPerformed

